function expectedValue(outcomes) {
  return outcomes.reduce((sum, o) => sum + o.pct * o.cost, 0) / 100;
}

function totalPct(outcomes) {
  return outcomes.reduce((sum, o) => sum + o.pct, 0);
}

function worstCase(outcomes) {
  return outcomes.reduce((max, o) => Math.max(max, o.cost), 0);
}

function tailPct(outcomes, threshold) {
  return outcomes
    .filter((o) => o.cost >= threshold)
    .reduce((sum, o) => sum + o.pct, 0);
}

function isValid(outcomes) {
  const total = outcomes.reduce((sum, o) => sum + o.pct, 0);
  return total === 100;
}

function survives(outcomes, threshold, maxPct) {
  const tail = outcomes
    .filter((o) => o.cost >= threshold)
    .reduce((sum, o) => sum + o.pct, 0);
  return tail <= maxPct;
}

function cheaperOption(a, b) {
  const ev = (outcomes) =>
    outcomes.reduce((sum, o) => sum + o.pct * o.cost, 0) / 100;
  return ev(a) <= ev(b) ? "a" : "b";
}

function breakevenPct(cheap, expensive, target) {
  return ((target - cheap) / (expensive - cheap)) * 100;
}

function recommend(options, threshold, maxPct) {
  const ev = (outcomes) =>
    outcomes.reduce((sum, o) => sum + o.pct * o.cost, 0) / 100;
  const tail = (outcomes) =>
    outcomes
      .filter((o) => o.cost >= threshold)
      .reduce((sum, o) => sum + o.pct, 0);
  const survivors = options.filter((opt) => tail(opt.outcomes) <= maxPct);
  if (survivors.length === 0) return null;
  let best = survivors[0];
  for (const opt of survivors) {
    if (ev(opt.outcomes) < ev(best.outcomes)) best = opt;
  }
  return best.name;
}

function summarize(name, outcomes, threshold) {
  const ev = outcomes.reduce((sum, o) => sum + o.pct * o.cost, 0) / 100;
  const worst = outcomes.reduce((max, o) => Math.max(max, o.cost), 0);
  const tail = outcomes
    .filter((o) => o.cost >= threshold)
    .reduce((sum, o) => sum + o.pct, 0);
  return { name, ev, worst, tail };
}

function safeEV(outcomes) {
  const total = outcomes.reduce((sum, o) => sum + o.pct, 0);
  if (total !== 100) {
    throw new Error("Chances must add up to 100, got " + total);
  }
  return outcomes.reduce((sum, o) => sum + o.pct * o.cost, 0) / 100;
}

function rankSurvivors(options, threshold, maxPct) {
  const ev = (outcomes) =>
    outcomes.reduce((sum, o) => sum + o.pct * o.cost, 0) / 100;
  const tail = (outcomes) =>
    outcomes
      .filter((o) => o.cost >= threshold)
      .reduce((sum, o) => sum + o.pct, 0);
  return options
    .map((opt, index) => ({ opt, index }))
    .filter(({ opt }) => tail(opt.outcomes) <= maxPct)
    .sort(
      (x, y) => ev(x.opt.outcomes) - ev(y.opt.outcomes) || x.index - y.index,
    )
    .map(({ opt }) => opt.name);
}
